def sumofFactors(n):
    # Initialize result
    result = 0

    # Iterate through all numbers from 1 to n
    for i in range(1, n + 1):
        # Check if i is a factor of n
        if n % i == 0:
            # Check if i is an even number
            if i % 2 == 0:
                # Add i to the result
                result += i

    # Return the sum of even factors
    return result

def newman_prime(n):
    """
    Find the nth Newman–Shanks–Williams prime number.

    Args:
    n (int): The position of the Newman–Shanks–Williams prime number to find.

    Returns:
    int: The nth Newman–Shanks–Williams prime number.

    Raises:
    ValueError: If n is less than 1.
    """
    if n < 1:
        raise ValueError("n must be greater than or equal to 1")

    memo = {0: 0, 1: 1}

    def is_prime(num):
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def nsw_number(k):
        """Calculate the kth Newman–Shanks–Williams number with memoization."""
        if k in memo:
            return memo[k]
        memo[k] = nsw_number(k - 1) + nsw_number(k - 2) + 1
        return memo[k]

    count = 0
    k = 0
    while True:
        nsw = nsw_number(k)
        if is_prime(nsw):
            count += 1
            if count == n:
                return nsw
        k += 1

def check_expression(expression):
    # Define a dictionary to hold matching pairs of parentheses
    matching_parentheses = {')': '(', '}': '{', ']': '['}
    # Initialize an empty stack to keep track of opening parentheses
    stack = []

    # Iterate through each character in the expression
    for char in expression:
        # If the character is an opening parenthesis, push it onto the stack
        if char in matching_parentheses.values():
            stack.append(char)
        # If the character is a closing parenthesis
        elif char in matching_parentheses:
            # If the stack is empty or the top of the stack doesn't match the corresponding opening parenthesis, return False
            if not stack or stack[-1] != matching_parentheses[char]:
                return False
            # Otherwise, pop the top of the stack
            stack.pop()

    # If the stack is empty, all parentheses were balanced; otherwise, return False
    return not stack

def unique_sublists(lst):
    """
    Counts the number of occurrences of each unique sublist in the given list.

    Args:
    lst (list of list): The list containing sublists to be counted.

    Returns:
    dict: A dictionary where keys are the unique sublists (converted to tuples) and values are their counts.
    """
    # Convert each sublist to a tuple and count occurrences
    sublist_counts = {}
    for sublist in lst:
        tuple_sublist = tuple(sublist)
        if tuple_sublist in sublist_counts:
            sublist_counts[tuple_sublist] += 1
        else:
            sublist_counts[tuple_sublist] = 1
    return sublist_counts

